describe("makeManualClock", () => {
  it("starts at 0 and advance(5) moves now() from 0 to 5", () => {
    const clock = makeManualClock();
    expect(clock.now()).toBe(0);
    clock.advance(5);
    expect(clock.now()).toBe(5);
  });

  it("honours a custom start and set()", () => {
