import { readdirSync, readFileSync, statSync } from "node:fs";
import { join, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

/** Wall-clock / nondeterminism tokens that must never appear under src/** (E11.7 / V1). */
const FORBIDDEN = ["Date.now(", "setTimeout(", "setInterval(", "performance.now(", "new Date()"];
/** The one production-only file allowed to read the wall clock (created by a later card). */
const ALLOWLIST = new Set(["src/kernel/system-clock.ts"]);

const REPO_ROOT = fileURLToPath(new URL("../../", import.meta.url));
const SRC_ROOT = join(REPO_ROOT, "src");

function listFiles(dir: string): string[] {
  const out: string[] = [];
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) {
      out.push(...listFiles(full));
    } else {
      out.push(full);
    }
  }
  return out;
}

describe("no wall-clock under src/**", () => {
  it("finds zero forbidden tokens outside the allowlisted system clock", () => {
    const offenders: string[] = [];
    for (const file of listFiles(SRC_ROOT)) {
      const rel = relative(REPO_ROOT, file).split(sep).join("/");
      if (ALLOWLIST.has(rel)) {
        continue;
      }
      const text = readFileSync(file, "utf8");
      for (const token of FORBIDDEN) {
        if (text.includes(token)) {
          offenders.push(`${rel}: ${token}`);
        }
      }
    }
    expect(offenders).toEqual([]);
  });
});

/** Logical clock: the ONLY time source src/** may use (determinism, E11.7 / V1). */
export interface Clock {
  /** Logical milliseconds since epoch 0. */
  now(): number;
}

/** A manually driven clock for simulation and tests. Time moves only when told to. */
export function makeManualClock(startMs = 0): Clock & { advance(ms: number): void; set(ms: number): void } {
  let t = startMs;
  return {
    now: () => t,
    advance(ms: number): void {
      if (ms < 0) {
        throw new RangeError(`advance(ms) requires ms >= 0, got ${ms}`);
      }
      t += ms;
    },
    set(ms: number): void {
      t = ms;
    },
  };
}

/** Seeded, forkable PRNG tree — the ONLY randomness source src/** may use (determinism, E11.7). */
export interface Prng {
  nextU32(): number;
  nextFloat(): number;
  fork(label: string): Prng;
  nextId(prefix: string): string;
}

/** FNV-1a over the label, mixed with the parent's state, so sibling forks are independent and reproducible. */
function hashLabel(label: string, parentState: number): number {
  let h = (0x811c9dc5 ^ parentState) >>> 0;
  for (let i = 0; i < label.length; i += 1) {
    h ^= label.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h >>> 0;
}

/** mulberry32: a small pure 32-bit generator. `fork` reads the parent state without advancing it. */
export function makePrngTree(seed: number): Prng {
  let state = seed >>> 0;
  const nextU32 = (): number => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return (t ^ (t >>> 14)) >>> 0;
  };
  return {
    nextU32,
    nextFloat: () => nextU32() / 2 ** 32,
    fork: (label: string) => makePrngTree(hashLabel(label, state)),
    nextId: (prefix: string) => `${prefix}-${nextU32().toString(36)}`,
  };
}

import { describe, expect, it } from "vitest";
import { makePrngTree, type Prng } from "../../src/kernel/prng";

const take = (prng: Prng, n: number): number[] => Array.from({ length: n }, () => prng.nextU32());

describe("makePrngTree", () => {
  it("two trees with the same seed produce identical first 5 nextU32() values", () => {
    expect(take(makePrngTree(42), 5)).toEqual(take(makePrngTree(42), 5));
  });

  it("fork(\"a\") and fork(\"b\") diverge; fork(\"a\") twice from the same parent state matches", () => {
    const parent = makePrngTree(42);
    const a1 = take(parent.fork("a"), 5);
    const b = take(parent.fork("b"), 5);
    const a2 = take(parent.fork("a"), 5);
    expect(a1).not.toEqual(b);
    expect(a1).toEqual(a2);
  });

  it("forks change once the parent advances, and different seeds differ", () => {
    const parent = makePrngTree(42);
    const before = take(parent.fork("a"), 3);
    parent.nextU32();
    expect(take(parent.fork("a"), 3)).not.toEqual(before);
    expect(take(makePrngTree(1), 5)).not.toEqual(take(makePrngTree(2), 5));
  });

  it("nextU32 is a uint32, nextFloat is in [0, 1), nextId carries the prefix", () => {
    const prng = makePrngTree(7);
    for (let i = 0; i < 200; i += 1) {
      const v = prng.nextU32();
      expect(Number.isInteger(v)).toBe(true);
      expect(v).toBeGreaterThanOrEqual(0);
      expect(v).toBeLessThanOrEqual(0xffffffff);
      const f = prng.nextFloat();
      expect(f).toBeGreaterThanOrEqual(0);
      expect(f).toBeLessThan(1);
    }
    expect(prng.nextId("evt")).toMatch(/^evt-[0-9a-z]+$/);
  });
});

import { z } from "zod";

/** Every domain event carries these fields; `seq` is the append-only log position, `at` the logical clock. */
export interface BaseEvent {
  id: string;
  seq: number;
  at: number;
  type: string;
}

/** A domain event is the base plus a per-type payload; the discriminated union grows as cards add types. */
export type DomainEvent = BaseEvent & { [k: string]: unknown };

const baseEventObject = z.object({
  id: z.string().min(1),
  seq: z.number().int().nonnegative(),
  at: z.number().int(),
  type: z.string().min(1),
});

export const baseEventSchema: z.ZodType<BaseEvent> = baseEventObject;

/** Event schemas by `type`, populated by `defineEvent`, so the log writer can validate any event by its type. */
export const eventRegistry = new Map<string, z.ZodTypeAny>();

/** Define an event type: the base fields, `type` narrowed to the literal, plus the payload shape. Registers it. */
export function defineEvent<TType extends string, TPayload extends z.ZodRawShape>(type: TType, payload: TPayload) {
  const schema = baseEventObject.extend({ type: z.literal(type), ...payload });
  eventRegistry.set(type, schema);
  return schema;
}

/** The registered schema for an event type, or undefined when no card has defined it. */
export function eventSchemaFor(type: string): z.ZodTypeAny | undefined {
  return eventRegistry.get(type);
}

import { describe, expect, it } from "vitest";
import { z } from "zod";
import { baseEventSchema, defineEvent, eventRegistry, eventSchemaFor } from "../../src/kernel/events";

describe("DomainEvent base + zod registry", () => {
  const testEvent = defineEvent("Test", { x: z.number() });

  it("parses a valid event", () => {
    const parsed = testEvent.parse({ id: "e1", seq: 0, at: 0, type: "Test", x: 1 });
    expect(parsed).toEqual({ id: "e1", seq: 0, at: 0, type: "Test", x: 1 });
  });

  it("throws on parse when seq is missing", () => {
    expect(() => testEvent.parse({ id: "e1", at: 0, type: "Test", x: 1 })).toThrow();
  });

  it("narrows type to the literal and rejects a negative or non-integer seq", () => {
    expect(() => testEvent.parse({ id: "e1", seq: 1, at: 0, type: "Other", x: 1 })).toThrow();
    expect(() => testEvent.parse({ id: "e1", seq: -1, at: 0, type: "Test", x: 1 })).toThrow();
    expect(() => testEvent.parse({ id: "e1", seq: 1.5, at: 0, type: "Test", x: 1 })).toThrow();
  });

  it("registers the schema by type for the log writer", () => {
    expect(eventRegistry.get("Test")).toBe(testEvent);
    expect(eventSchemaFor("Test")).toBe(testEvent);
    expect(eventSchemaFor("Unknown")).toBeUndefined();
  });

  it("baseEventSchema accepts any type string", () => {
    expect(baseEventSchema.parse({ id: "b", seq: 3, at: 10, type: "Any" })).toEqual({ id: "b", seq: 3, at: 10, type: "Any" });
  });
});

import { describe, expect, it } from "vitest";
import { z } from "zod";
import { fold, makeEventLog } from "../../src/kernel/event-log";
import { type DomainEvent, defineEvent } from "../../src/kernel/events";
import { makePrngTree } from "../../src/kernel/prng";

defineEvent("Added", { x: z.number() });

describe("append-only event log + fold", () => {
  it("appending 3 events yields seq 0,1,2 with prng ids and frozen events", () => {
    const log = makeEventLog(makePrngTree(1));
    const events = [1, 2, 3].map((x) => log.append({ at: x, type: "Added", x }));
    expect(events.map((e) => e.seq)).toEqual([0, 1, 2]);
    expect(events.every((e) => e.id.startsWith("ev-") && Object.isFrozen(e))).toBe(true);
    expect(() => {
      (events[0] as unknown as { x: number }).x = 99;
    }).toThrow();
  });

  it("all() is frozen — mutating throws", () => {
    const log = makeEventLog(makePrngTree(2));
    log.append({ at: 0, type: "Added", x: 1 });
    const all = log.all();
    expect(Object.isFrozen(all)).toBe(true);
    expect(() => {
      (all as DomainEvent[]).push({ id: "x", seq: 9, at: 0, type: "Added" });
    }).toThrow();
    expect(log.all()).toHaveLength(1);
  });

  it("fold sums the x payload", () => {
    const log = makeEventLog(makePrngTree(3));
    const xs = [4, 5, 6];
    for (const x of xs) log.append({ at: 0, type: "Added", x });
    expect(fold(log, 0, (s, e) => s + Number(e.x))).toBe(xs.reduce((a, b) => a + b, 0));
  });

  it("appending an unregistered type throws, and an invalid payload throws", () => {
    const log = makeEventLog(makePrngTree(4));
    expect(() => log.append({ at: 0, type: "Nope" })).toThrow(RangeError);
    expect(() => log.append({ at: 0, type: "Added", x: "not a number" })).toThrow();
    expect(log.all()).toHaveLength(0);
  });
});

import { type BaseEvent, type DomainEvent, eventSchemaFor } from "./events";
import type { Prng } from "./prng";

/** What a caller appends: the base fields minus the log-assigned id/seq, plus the per-type payload. */
export type NewEvent = Omit<BaseEvent, "id" | "seq"> & { [k: string]: unknown };

/** Truth is the log (E1): append-only, every event validated by its registered schema and frozen (E11.2). */
export interface EventLog {
  append(e: NewEvent): DomainEvent;
  all(): readonly DomainEvent[];
}

export function makeEventLog(prng: Prng): EventLog {
  const events: DomainEvent[] = [];
  return {
    append(e) {
      const schema = eventSchemaFor(e.type);
      if (!schema) {
        throw new RangeError(`append: unknown event type "${e.type}" — define it with defineEvent first`);
      }
      const parsed = schema.parse({ ...e, id: prng.nextId("ev"), seq: events.length }) as DomainEvent;
      const frozen = Object.freeze({ ...parsed });
      events.push(frozen);
      return frozen;
    },
    all: () => Object.freeze([...events]),
  };
}

/** Left-fold the whole log into a state — the only way state is derived (pure fold, E1). */
export function fold<S>(log: EventLog, init: S, reducer: (s: S, e: DomainEvent) => S): S {
  return log.all().reduce(reducer, init);
}

import { describe, expect, it } from "vitest";
import { z } from "zod";
import { makeEventLog } from "../../src/kernel/event-log";
import { defineEvent } from "../../src/kernel/events";
import { makePrngTree } from "../../src/kernel/prng";
import { restore, snapshot } from "../../src/kernel/snapshot";

defineEvent("Snap", { x: z.number() });

describe("snapshot / restore", () => {
  it("restore(snapshot(log)).all() deep-equals log.all(), and the restored log keeps appending correctly", () => {
    const log = makeEventLog(makePrngTree(7));
    for (const x of [1, 2, 3]) log.append({ at: x, type: "Snap", x });
    const restored = restore(snapshot(log), makePrngTree(99));
    expect(restored.all()).toEqual(log.all());
    expect(Object.isFrozen(restored.all()[0])).toBe(true);
    const next = restored.append({ at: 4, type: "Snap", x: 4 });
    expect(next.seq).toBe(3);
    expect(restored.all()).toHaveLength(4);
  });

  it("a tampered snapshot throws on restore", () => {
    const log = makeEventLog(makePrngTree(7));
    log.append({ at: 1, type: "Snap", x: 1 });
    const badType = snapshot(log).replace('"Snap"', '"Forged"');
    expect(() => restore(badType, makePrngTree(1))).toThrow(RangeError);
    const badPayload = snapshot(log).replace('"x":1', '"x":"one"');
    expect(() => restore(badPayload, makePrngTree(1))).toThrow();
    const badSeq = snapshot(log).replace('"seq":0', '"seq":5');
    expect(() => restore(badSeq, makePrngTree(1))).toThrow(RangeError);
    expect(() => restore("{}", makePrngTree(1))).toThrow(RangeError);
  });
});

import type { EventLog } from "./event-log";
import { type DomainEvent, eventSchemaFor } from "./events";
import type { Prng } from "./prng";

/** JSON of every event — the whole truth, in order (E1). */
export function snapshot(log: EventLog): string {
  return JSON.stringify(log.all());
}

/** An EventLog preloaded with already-validated events; append keeps the S05 rules (schema, seq, id, freeze). */
function makeLogFromEvents(preloaded: readonly DomainEvent[], prng: Prng): EventLog {
  const events: DomainEvent[] = preloaded.map((event) => Object.freeze({ ...event }));
  return {
    append(e) {
      const schema = eventSchemaFor(e.type);
      if (!schema) {
        throw new RangeError(`append: unknown event type "${e.type}" — define it with defineEvent first`);
      }
      const parsed = schema.parse({ ...e, id: prng.nextId("ev"), seq: events.length }) as DomainEvent;
      const frozen = Object.freeze({ ...parsed });
      events.push(frozen);
      return frozen;
    },
    all: () => Object.freeze([...events]),
  };
}

/** Rebuild a log from a snapshot, re-validating every event against the registry; tampering throws. */
export function restore(json: string, prng: Prng): EventLog {
  const raw: unknown = JSON.parse(json);
  if (!Array.isArray(raw)) {
    throw new RangeError("restore: snapshot must be a JSON array of events");
  }
  const events = raw.map((entry, index) => {
    const type = typeof entry === "object" && entry !== null ? (entry as { type?: unknown }).type : undefined;
    const schema = typeof type === "string" ? eventSchemaFor(type) : undefined;
    if (!schema) {
      throw new RangeError(`restore: event ${index} has unknown type "${String(type)}"`);
    }
    const event = schema.parse(entry) as DomainEvent;
    if (event.seq !== index) {
      throw new RangeError(`restore: event ${index} carries seq ${event.seq} — the log is append-only and dense`);
    }
    return event;
  });
  return makeLogFromEvents(events, prng);
}

/** Trust labels, weakest first. Authority is typed by trust (E2 / E11.3); taint propagates to the weakest label. */
export const TRUST_ORDER = [
  "adversarial-quarantined",
  "web-scraped-untrusted",
  "model-generated",
  "community-claim",
  "benchmarked",
  "first-party-verified",
  "owner-stated",
] as const;

export type Trust = (typeof TRUST_ORDER)[number];

/** Rank = index in TRUST_ORDER (0 = weakest). */
export function trustRank(t: Trust): number {
  const rank = TRUST_ORDER.indexOf(t);
  if (rank < 0) {
    throw new RangeError(`Unknown trust label: ${String(t)}`);
  }
  return rank;
}

/** True when `value` is at least as trusted as `required`. */
export function meetsMin(value: Trust, required: Trust): boolean {
  return trustRank(value) >= trustRank(required);
}

/** The lower-ranked of two labels — what a derived value inherits under taint propagation. */
export function weakest(a: Trust, b: Trust): Trust {
  return trustRank(a) <= trustRank(b) ? a : b;
}

/** True for the label a value must carry to be treated as untrusted input. */
export function isUntrusted(t: Trust): boolean {
  return trustRank(t) <= trustRank("web-scraped-untrusted");
}

import { describe, expect, it } from "vitest";
import { TRUST_ORDER, isUntrusted, meetsMin, trustRank, weakest } from "../../src/trust/trust";

describe("trust labels + ordering", () => {
  it("ranks follow TRUST_ORDER, weakest first", () => {
    expect(TRUST_ORDER[0]).toBe("adversarial-quarantined");
    expect(TRUST_ORDER[TRUST_ORDER.length - 1]).toBe("owner-stated");
    TRUST_ORDER.forEach((label, index) => expect(trustRank(label)).toBe(index));
  });

  it("meetsMin compares ranks", () => {
    expect(meetsMin("owner-stated", "first-party-verified")).toBe(true);
    expect(meetsMin("web-scraped-untrusted", "first-party-verified")).toBe(false);
    expect(meetsMin("benchmarked", "benchmarked")).toBe(true);
  });

  it("weakest picks the lower-ranked label (taint propagation)", () => {
    expect(weakest("benchmarked", "model-generated")).toBe("model-generated");
    expect(weakest("model-generated", "benchmarked")).toBe("model-generated");
    expect(weakest("owner-stated", "owner-stated")).toBe("owner-stated");
  });

  it("untrusted labels are the two weakest", () => {
    expect(isUntrusted("adversarial-quarantined")).toBe(true);
    expect(isUntrusted("web-scraped-untrusted")).toBe(true);
    expect(isUntrusted("model-generated")).toBe(false);
  });

  it("rejects an unknown label at runtime", () => {
    expect(() => trustRank("made-up" as never)).toThrow(RangeError);
  });
});

import { describe, expect, it } from "vitest";
import { combineTainted, mapTainted, taint, type Tainted, verify, type VerificationEvent } from "../../src/trust/tainted";
import { TRUST_ORDER, type Trust, trustRank } from "../../src/trust/trust";

describe("tainted values + monotone propagation", () => {
  it("mapTainted preserves trust and provenance", () => {
    const t = mapTainted(taint(2, "benchmarked", "bench"), (n) => n * 10);
    expect(t).toEqual({ value: 20, trust: "benchmarked", provenance: "bench" });
  });

  it("combineTainted takes the weakest trust", () => {
    const owner = taint("a", "owner-stated", "owner");
    const webScraped = taint("b", "web-scraped-untrusted", "web");
    const combined = combineTainted(owner, webScraped, (x, y) => x + y);
    expect(combined.trust).toBe("web-scraped-untrusted");
    expect(combined.value).toBe("ab");
  });

  it("verify emits exactly one event and raises trust; lowering is refused", () => {
    const events: VerificationEvent[] = [];
    const raised = verify(taint(1, "model-generated", "m"), "first-party-verified", (e) => events.push(e));
    expect(raised.trust).toBe("first-party-verified");
    expect(events).toEqual([{ kind: "trust.verified", from: "model-generated", to: "first-party-verified", provenance: "m" }]);
    expect(() => verify(raised, "community-claim", (e) => events.push(e))).toThrow(RangeError);
    expect(events).toHaveLength(1);
  });

  it("tainted values are frozen — trust cannot be assigned", () => {
    const t = taint(1, "benchmarked", "b");
    expect(Object.isFrozen(t)).toBe(true);
    expect(() => {
      (t as { trust: Trust }).trust = "owner-stated";
    }).toThrow();
  });

  it("property: over 1000 random transform chains, output trust never exceeds the weakest input unless verify emitted", () => {
    // Deterministic inline LCG (tests may not use Math.random either).
    let state = 123456789;
    const rnd = (): number => {
      state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
      return state / 2 ** 32;
    };
    const pick = (): Trust => TRUST_ORDER[Math.floor(rnd() * TRUST_ORDER.length)] as Trust;
    for (let run = 0; run < 1000; run += 1) {
      const events: VerificationEvent[] = [];
      let weakestInput = 6;
      const start = pick();
      weakestInput = Math.min(weakestInput, trustRank(start));
      let current: Tainted<number> = taint(0, start, "seed");
      const steps = 1 + Math.floor(rnd() * 8);
      for (let i = 0; i < steps; i += 1) {
        const op = rnd();
        if (op < 0.4) {
          current = mapTainted(current, (n) => n + 1);
        } else if (op < 0.8) {
          const other = pick();
          weakestInput = Math.min(weakestInput, trustRank(other));
          current = combineTainted(current, taint(1, other, "in"), (a, b) => a + b);
        } else {
          const to = pick();
          if (trustRank(to) >= trustRank(current.trust)) {
            current = verify(current, to, (e) => events.push(e));
          }
        }
      }
      if (events.length === 0) {
        expect(trustRank(current.trust)).toBeLessThanOrEqual(weakestInput);
      }
    }
  });
});

import { meetsMin, type Trust, weakest } from "./trust";

/** A value carrying the trust of its provenance. Immutable: trust can change ONLY through `verify`. */
export interface Tainted<T> {
  readonly value: T;
  readonly trust: Trust;
  readonly provenance: string;
}

/** Emitted to the audit sink every time trust is raised — the only path that raises it (E2 / E11.5). */
export interface VerificationEvent {
  readonly kind: "trust.verified";
  readonly from: Trust;
  readonly to: Trust;
  readonly provenance: string;
}

export function taint<T>(value: T, trust: Trust, provenance: string): Tainted<T> {
  return Object.freeze({ value, trust, provenance });
}

/** Transform the value; trust and provenance are kept (monotone). */
export function mapTainted<A, B>(t: Tainted<A>, f: (a: A) => B): Tainted<B> {
  return taint(f(t.value), t.trust, t.provenance);
}

/** Combine two values; the result carries the WEAKEST of the two trusts. */
export function combineTainted<A, B, C>(a: Tainted<A>, b: Tainted<B>, f: (a: A, b: B) => C): Tainted<C> {
  return taint(f(a.value, b.value), weakest(a.trust, b.trust), `${a.provenance}+${b.provenance}`);
}

/**
 * The ONLY way to raise trust: re-label `t` at `to` (rank must be >= the current rank) and emit exactly one
 * VerificationEvent to the audit sink. Lowering through verify is refused; nothing else mutates trust.
 */
export function verify<T>(t: Tainted<T>, to: Trust, auditSink: (e: VerificationEvent) => void): Tainted<T> {
  if (!meetsMin(to, t.trust)) {
    throw new RangeError(`verify() can only raise trust: ${t.trust} -> ${to}`);
  }
  auditSink({ kind: "trust.verified", from: t.trust, to, provenance: t.provenance });
  return taint(t.value, to, t.provenance);
}

import { describe, expect, it } from "vitest";
import { attenuate, type Capability, isValid, mintRoot, type Prng, revoke } from "../../src/auth/capability";

function stubPrng(): Prng {
  let n = 0;
  return { nextId: (prefix) => `${prefix}-${(n += 1)}` };
}

describe("capability token kernel", () => {
  const root = (): Capability =>
    mintRoot({ scope: "ops", cap: 100, minorUnits: 50_000, expiresAt: 1_000 }, stubPrng());

  it("mintRoot has no parent and is valid before expiry", () => {
    const r = root();
    expect(r).toMatchObject({ id: "cap-1", parentId: null, revoked: false });
    expect(isValid(r, 999)).toBe(true);
    expect(isValid(r, 1_000)).toBe(false);
  });

  it("attenuating to a smaller cap works; a larger cap throws", () => {
    const r = root();
    const child = attenuate(r, { cap: 40 }, stubPrng());
    expect(child).toMatchObject({ cap: 40, scope: "ops", expiresAt: 1_000, minorUnits: 50_000, parentId: "cap-1" });
    expect(() => attenuate(r, { cap: 101 }, stubPrng())).toThrow(RangeError);
    expect(() => attenuate(r, { expiresAt: 1_001 }, stubPrng())).toThrow(RangeError);
    expect(() => attenuate(r, { minorUnits: 50_001 }, stubPrng())).toThrow(RangeError);
    expect(() => attenuate(r, { scope: "finance" }, stubPrng())).toThrow(RangeError);
    expect(attenuate(r, { scope: "ops:read" }, stubPrng()).scope).toBe("ops:read");
  });

  it("an expired or revoked token is invalid; revoke returns a copy and blocks attenuation", () => {
    const r = root();
    expect(isValid(r, 5_000)).toBe(false);
    const dead = revoke(r);
    expect(dead.revoked).toBe(true);
    expect(r.revoked).toBe(false);
    expect(isValid(dead, 0)).toBe(false);
    expect(() => attenuate(dead, {}, stubPrng())).toThrow(RangeError);
  });

  it("property: over 500 fuzzed attenuation chains no descendant is stronger than any ancestor on any field", () => {
    let state = 987654321;
    const rnd = (): number => {
      state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
      return state / 2 ** 32;
    };
    for (let run = 0; run < 500; run += 1) {
      const prng = stubPrng();
      const chain: Capability[] = [mintRoot({ scope: "s", cap: 1_000, minorUnits: 1_000, expiresAt: 10_000 }, prng)];
      const depth = 1 + Math.floor(rnd() * 6);
      for (let i = 0; i < depth; i += 1) {
        const parent = chain[chain.length - 1] as Capability;
        const request = {
          ...(rnd() < 0.5 ? { cap: Math.floor(rnd() * (parent.cap + 1)) } : {}),
          ...(rnd() < 0.5 ? { expiresAt: Math.floor(rnd() * (parent.expiresAt + 1)) } : {}),
          ...(rnd() < 0.5 ? { minorUnits: Math.floor(rnd() * ((parent.minorUnits ?? 0) + 1)) } : {}),
          ...(rnd() < 0.5 ? { scope: `${parent.scope}:${Math.floor(rnd() * 10)}` } : {}),
        };
        chain.push(attenuate(parent, request, prng));
        if (rnd() < 0.3) {
          const tooStrong = attenuate.bind(null, parent, { cap: parent.cap + 1 }, prng);
          expect(tooStrong).toThrow(RangeError);
        }
      }
      for (let a = 0; a < chain.length; a += 1) {
        for (let d = a + 1; d < chain.length; d += 1) {
          const ancestor = chain[a] as Capability;
          const descendant = chain[d] as Capability;
          expect(descendant.cap).toBeLessThanOrEqual(ancestor.cap);
          expect(descendant.expiresAt).toBeLessThanOrEqual(ancestor.expiresAt);
          expect(descendant.minorUnits ?? 0).toBeLessThanOrEqual(ancestor.minorUnits ?? 0);
          expect(descendant.scope.startsWith(ancestor.scope)).toBe(true);
        }
      }
    }
  });
});

/** Capability tokens: attenuation can only weaken; only the owner/constitution mints roots (V5 / V8.8–V8.9). */
export interface Capability {
  id: string;
  scope: string;
  cap: number;
  minorUnits?: number;
  expiresAt: number;
  parentId: string | null;
  revoked: boolean;
}

/** The id source the kernel needs; S03's `Prng` satisfies it structurally (`nextId`). */
export interface Prng {
  nextId(prefix: string): string;
}

/** Mint a root token (owner/constitution only): no parent, not revoked. */
export function mintRoot(grant: Omit<Capability, "id" | "parentId" | "revoked">, prng: Prng): Capability {
  return Object.freeze({ ...grant, id: prng.nextId("cap"), parentId: null, revoked: false });
}

/** Sub-scope = string prefix match on the parent scope (the spec's rule). */
export function isSubScope(parent: string, child: string): boolean {
  return child.startsWith(parent);
}

/**
 * Derive a child no stronger than its parent on ANY field. Unspecified fields inherit (clamp to the parent);
 * a requested field that would exceed the parent throws — a stronger descendant is impossible by construction.
 */
export function attenuate(
  parent: Capability,
  child: Partial<Pick<Capability, "scope" | "cap" | "minorUnits" | "expiresAt">>,
  prng: Prng,
): Capability {
  if (parent.revoked) {
    throw new RangeError("attenuate: parent capability is revoked");
  }
  const scope = child.scope ?? parent.scope;
  if (!isSubScope(parent.scope, scope)) {
    throw new RangeError(`attenuate: scope "${scope}" is not within "${parent.scope}"`);
  }
  const cap = child.cap ?? parent.cap;
  if (cap > parent.cap) {
    throw new RangeError(`attenuate: cap ${cap} exceeds parent cap ${parent.cap}`);
  }
  const expiresAt = child.expiresAt ?? parent.expiresAt;
  if (expiresAt > parent.expiresAt) {
    throw new RangeError(`attenuate: expiresAt ${expiresAt} exceeds parent ${parent.expiresAt}`);
  }
  const minorUnits = child.minorUnits ?? parent.minorUnits;
  if (parent.minorUnits !== undefined && minorUnits !== undefined && minorUnits > parent.minorUnits) {
    throw new RangeError(`attenuate: minorUnits ${minorUnits} exceeds parent ${parent.minorUnits}`);
  }
  return Object.freeze({
    id: prng.nextId("cap"),
    scope,
    cap,
    ...(minorUnits === undefined ? {} : { minorUnits }),
    expiresAt,
    parentId: parent.id,
    revoked: false,
  });
}

export function isValid(c: Capability, now: number): boolean {
  return !c.revoked && now < c.expiresAt;
}

/** A revoked copy; the original is untouched (tokens are frozen). */
export function revoke(c: Capability): Capability {
  return Object.freeze({ ...c, revoked: true });
}

import { describe, expect, it } from "vitest";
import { type AuditFields, emitAudit, sha256Hex, stableStringify } from "../../src/audit/audit";
import { makeEventLog } from "../../src/kernel/event-log";
import { makePrngTree } from "../../src/kernel/prng";

const fields: AuditFields = {
  at: 10,
  actor: "factory",
  brainVersion: "b1",
  modelVersion: "m1",
  toolVersion: "t1",
  inputsHash: sha256Hex(stableStringify({ b: 1, a: [2, { d: 3, c: 4 }] })),
  outputSummary: "published landing page",
  approvalSource: "policy",
  financialImpactMinor: 0,
  rollbackRef: null,
  sideEffectId: "se-1",
};

describe("audit event + emitter", () => {
  it("emitting a valid audit appends exactly one AuditEvent", () => {
    const log = makeEventLog(makePrngTree(1));
    const event = emitAudit(log, fields);
    expect(log.all()).toHaveLength(1);
    expect(event).toMatchObject({ type: "AuditEvent", seq: 0, at: 10, sideEffectId: "se-1", approvalSource: "policy" });
  });

  it("a missing sideEffectId throws and nothing is appended", () => {
    const log = makeEventLog(makePrngTree(1));
    const { sideEffectId: _omitted, ...missing } = fields;
    expect(() => emitAudit(log, missing as unknown as AuditFields)).toThrow();
    expect(() => emitAudit(log, { ...fields, financialImpactMinor: 1.5 })).toThrow();
    expect(log.all()).toHaveLength(0);
  });

  it("sha256Hex is stable and known; stableStringify sorts keys at every level", () => {
    expect(sha256Hex("a")).toBe("ca978112ca1bbdcafac231b39a23dc4da786eff8147c4e72b9807785afee48bb");
    expect(stableStringify({ b: 1, a: { d: 2, c: [3, { f: 4, e: 5 }] } })).toBe('{"a":{"c":[3,{"e":5,"f":4}],"d":2},"b":1}');
    expect(sha256Hex(stableStringify({ x: 1, y: 2 }))).toBe(sha256Hex(stableStringify({ y: 2, x: 1 })));
  });
});

import { createHash } from "node:crypto";
import { z } from "zod";
import type { EventLog } from "../kernel/event-log";
import { defineEvent, type DomainEvent } from "../kernel/events";

/** Audit totality (E11.2): every side effect leaves exactly one AuditEvent with these fields. */
export const auditEventSchema = defineEvent("AuditEvent", {
  actor: z.string(),
  brainVersion: z.string(),
  modelVersion: z.string(),
  toolVersion: z.string(),
  inputsHash: z.string(),
  outputSummary: z.string(),
  approvalSource: z.enum(["policy", "owner", "none"]),
  financialImpactMinor: z.number().int(),
  rollbackRef: z.string().nullable(),
  sideEffectId: z.string(),
});

/** The caller-supplied audit fields: the payload plus the logical time `at`. */
export type AuditFields = {
  at: number;
  actor: string;
  brainVersion: string;
  modelVersion: string;
  toolVersion: string;
  inputsHash: string;
  outputSummary: string;
  approvalSource: "policy" | "owner" | "none";
  financialImpactMinor: number;
  rollbackRef: string | null;
  sideEffectId: string;
};

export function sha256Hex(input: string): string {
  return createHash("sha256").update(input).digest("hex");
}

/** JSON with sorted object keys at every level (§C3) so `inputsHash` is stable across key order. */
export function stableStringify(value: unknown): string {
  if (Array.isArray(value)) {
    return `[${value.map((item) => stableStringify(item)).join(",")}]`;
  }
  if (value !== null && typeof value === "object") {
    const entries = Object.entries(value as Record<string, unknown>).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
    return `{${entries.map(([key, item]) => `${JSON.stringify(key)}:${stableStringify(item)}`).join(",")}}`;
  }
  return JSON.stringify(value) ?? "null";
}

/** Validate (the schema throws on a missing field) and append one AuditEvent. */
export function emitAudit(log: EventLog, a: AuditFields): DomainEvent {
  const { at, ...payload } = a;
  auditEventSchema.omit({ id: true, seq: true }).parse({ ...payload, at, type: "AuditEvent" });
  return log.append({ ...payload, at, type: "AuditEvent" });
}
